INSERT INTO feature VALUES('builtin-declarations','types','Builtin rows bound in std','native-primitives','partial','ordinary',NULL,'One table in `gandr-core-term` holds each builtin row under its key, the name the tree knows it by. A module of `std` binds a row with the mark `@[builtin("key")]`. A given row, a native value, takes a signature with no body: the row gives the value, and a call of the declaration lowers as a call of the row. A found row, a role, takes a declaration with its body. A mark outside the toolchain, a key that names no row, a body on a given row, no body on a found row, a type that is not the row''s and a second holder of a row are each refused by name. `std.string` binds `string.append` alone, and every other native row keeps its reserved name.','core-term surface-lowering surface-lowering-expression','library/std/src/string.gandr','corpus/ledger/features/builtin-declarations.gandr','#7833 #8071');
